package org.sleepwell.app;
import android.app.Activity;import android.content.*;import android.os.Bundle;import android.view.*;import android.widget.*;import java.util.*;
/** Public GET_CONTENT picker for one allowlisted custom summary. Explicit user Share is mandatory. */
public final class SleepSummaryActivity extends Activity implements SleepSummaryJob.Observer {
 private SleepSummaryJob job;private String caller,error="";private boolean resumed,returned;
 @Override public void onCreate(Bundle saved){super.onCreate(saved);setResult(RESULT_CANCELED);caller=getCallingPackage();try{validate(getIntent());if(caller==null||caller.isBlank())throw new IllegalArgumentException("Open this summary picker from a requesting app’s Get content action.");}catch(RuntimeException invalid){error="Unsupported summary request. Use Android Get content with the SleepWell summary MIME type, without a data URI or attached content.";render(null);return;}Object retained=getLastNonConfigurationInstance();int days=saved==null?7:saved.getInt("days",7);job=retained instanceof SleepSummaryJob?(SleepSummaryJob)retained:new SleepSummaryJob(getApplicationContext(),days,saved!=null);job.observe(this);}
 private static void validate(Intent input){if(input==null||!Intent.ACTION_GET_CONTENT.equals(input.getAction())||!SleepSummaryFileProvider.MIME.equals(input.getType())||input.getData()!=null||input.getClipData()!=null||input.getSelector()!=null)throw new IllegalArgumentException("Unsupported summary request.");}
 @Override protected void onNewIntent(Intent input){super.onNewIntent(input);setIntent(input);if(job!=null){job.detach(this);job.close();job=null;}try{validate(input);}catch(RuntimeException invalid){}error="A new document request arrived. Nothing was shared. Close this screen and request the summary again.";render(null);}
 @Override public Object onRetainNonConfigurationInstance(){return job;}
 public void changed(SleepSummaryJob.State state){if(isDestroyed())return;if(state.phase==SleepSummaryJob.Phase.VERIFIED){if(resumed&&hasWindowFocus()&&!isFinishing()){try{Intent result=new Intent().setDataAndType(state.uri,SleepSummaryFileProvider.MIME).addFlags(Intent.FLAG_GRANT_READ_URI_PERMISSION);result.setClipData(ClipData.newRawUri("SleepWell sleep summary",state.uri));job.shared();returned=true;setResult(RESULT_OK,result);finish();return;}catch(RuntimeException failure){error="The summary could not be returned. Nothing was automatically uploaded.";}}else{job.revokeShare();return;}}render(state);}
 private void render(SleepSummaryJob.State state){LinearLayout body=Design.page(this,false,null,n->{});RecordUi.header(body,"Share sleep summary",this::finish);Design.space(body,12);if(!error.isEmpty()){Design.text(body,error,15,500,Design.BROWN);Design.button(RecordUi.footer(body),"Cancel",false,this::finish);return;}Design.text(body,"Requested by "+caller,13,500,Design.MUTED);Design.space(body,8);Design.text(body,"Only this reviewed JSON document is returned, with temporary read access. The requesting app may keep or share its copy.",14,400,Design.MUTED);Design.space(body,12);LinearLayout periods=RecordUi.segments(body,new String[]{"7 days","30 days"},state.days==30?1:0,n->job.prepare(n==1?30:7));RecordUi.enabled(periods,!state.busy());SleepSummaryFiles.Snapshot snapshot=state.snapshot;if(snapshot!=null){SleepSummary.Data data=snapshot.data;Design.space(body,12);Design.text(body,data.from+" – "+data.through+" · "+data.zone,14,500,Design.INK);Design.item(body,"moon","Closed periods",Integer.toString(data.rows.size()),null);Design.item(body,"clock","Sum of reviewed durations",RecordUi.duration(data.total),null);Design.item(body,"check","Unique reviewed coverage",RecordUi.duration(data.unique),null);Design.text(body,"Overlaps count once in unique coverage. Manual, provider and legacy timing are labeled separately.",12,400,Design.MUTED);if(data.rejected>0)Design.text(body,data.rejected+" invalid closed records in this date window rejected.",12,500,Design.BROWN);Design.space(body,12);Design.text(body,"Included dates, provenance and duration",16,600,Design.INK);for(SleepSummary.Row row:data.rows){Design.space(body,6);Design.text(body,row.date+" · "+source(row.source)+" · "+RecordUi.duration(row.duration),13,400,Design.MUTED);}Design.space(body,12);Design.text(body,"JSON v1 · "+data.bytes.length+" bytes · SHA-256 "+snapshot.sha,10,400,Design.MUTED);}Design.space(body,12);Design.text(body,"Includes reviewed start/end times, known time zones, source/provenance, duration and edited/interrupted/clock-change flags. It is not a validated sleep or health measure.",12,400,Design.MUTED);Design.space(body,8);Design.text(body,"Excludes diary, notes, tags, ratings, audio, detailed sound events, raw sensors, credentials, sensor configuration and device/provider IDs. This is not a restore backup.",13,500,Design.BROWN);if(!state.message.isEmpty()){Design.space(body,12);Design.text(body,state.message,13,500,Design.BROWN);}LinearLayout footer=RecordUi.footer(body);Design.button(footer,state.phase==SleepSummaryJob.Phase.VERIFYING?"Verifying…":"Share summary",true,()->{if(resumed&&hasWindowFocus())job.verifyShare();}).setEnabled(state.phase==SleepSummaryJob.Phase.READY&&snapshot!=null&&!snapshot.data.rows.isEmpty());if(state.phase==SleepSummaryJob.Phase.ERROR)Design.button(footer,"Prepare again",false,()->job.prepare(state.days));Design.button(footer,"Cancel",false,this::finish);}
 private static String source(String value){return switch(value){case "user_reported"->"User reported";case "provider_import"->"Provider import";case "tracked"->"Phone/sonar recording";case "legacy_timing"->"Legacy timing";default->"Unknown source";};}
 @Override protected void onResume(){super.onResume();resumed=true;}
 @Override protected void onPause(){resumed=false;if(job!=null&&!returned)job.revokeShare();super.onPause();}
 @Override public void onWindowFocusChanged(boolean focused){super.onWindowFocusChanged(focused);if(focused)RecordUi.lightBars(this);else if(job!=null&&!returned)job.revokeShare();}
 @Override public void onSaveInstanceState(Bundle saved){super.onSaveInstanceState(saved);if(job!=null)saved.putInt("days",job.state().days);}
 @Override protected void onDestroy(){if(job!=null){job.detach(this);if(!isChangingConfigurations())job.close();}super.onDestroy();}
}
